SELECT jsonb_build_object('events',(SELECT jsonb_agg(to_jsonb(x) ORDER BY data_inicial,id_evento) FROM (SELECT e.id_evento,e.nome_evento,e.tag,e.data_inicial,e.data_final,e.cidade,e.estado,e.ativo,e.url_hotsite,e.url_inscricao,e.id_agrega_evento,md5(to_jsonb(e)::text) AS row_hash,(SELECT coalesce(jsonb_agg(to_jsonb(ge)),'[]') FROM tb_agregadores_eventos ge WHERE ge.id_evento=e.id_evento) AS memberships FROM tb_evento_corridas e WHERE e.ativo AND e.data_final>=current_date AND (e.nome_evento ILIKE '%live%run%' OR e.url_hotsite ILIKE '%liverun.com.br%' OR e.url_hotsite ILIKE '%appliveexperience.com.br%' OR e.nome_evento ILIKE '%estações%' OR EXISTS(SELECT 1 FROM tb_agregadores_eventos ge WHERE ge.id_evento=e.id_evento AND ge.agregador_tag IN ('live-run-xp','estacoes'))))x),'counts',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT ge.agregador_tag,count(*) AS linked,count(*) FILTER(WHERE e.ativo AND e.data_final>=current_date) AS upcoming FROM tb_agregadores_eventos ge JOIN tb_evento_corridas e USING(id_evento) WHERE ge.agregador_tag IN ('live-run-xp','estacoes') GROUP BY ge.agregador_tag)x))::text payload
